    reverse((v).begin(), (v).end());
    double res = 0;
    for (int(i) = 0; (i) < (N); (i)++)
      res = max(res, ((double)D - v[i].first) / v[i].second);
    cout << fixed << setprecision(9) << D / res << endl;
  }
}
